# 长按橙色键会写这个"听写开窗"文件（内容=wall-clock 到期时间戳）。voice_agent 读到它没过期，
# 就把这段时间当作对话窗——你说的话不用喊唤醒词，直接被路由执行。见 ptt_arm.py。
PTT_ARM_PATH = os.environ.get(
    "SUNSET_PTT_ARM_PATH",
    os.path.join(os.path.expanduser("~"), ".local", "share", "sunset-radio", "voice-ptt-arm"),
)


def _ptt_arm_active():
    try:
        with open(PTT_ARM_PATH, "r", encoding="utf-8") as handle:
            return float(handle.read().strip() or 0) > time.time()
    except (OSError, ValueError):
        return False


def voice_window_open(now=None):
    mono = now if now is not None else time.monotonic()
    if mono < armed_until:
        return True
    # 长按开的窗（跨进程，走文件）也算窗口开着。
    return _ptt_arm_active()


def route_transcript(text, dry_run=False):
    global armed_until
    text = clean_transcript(text)
    if not text:
        return ""

    now = time.monotonic()
    match = wake_match(text)
    is_wake = bool(match)
    is_wake_word_guide = bool(WAKE_WORD_GUIDE_RE.search(text))
    was_open = voice_window_open(now)
    is_hotspot_connect = bool(HOTSPOT_CONNECT_GATE_RE.search(text) and not HOTSPOT_CONNECT_QUESTION_RE.search(text))
    is_negative_city_action_safety = bool(
        NEGATIVE_CITY_ACTION_SAFETY_RE.search(text)
        and not NEGATIVE_CITY_QUERY_GUARD_RE.search(text)
    )
    is_safety = bool(
        SAFETY_RE.search(text)
        or PORTABLE_COMFORT_RE.search(text)
        or PORTABLE_QUIET_NL_RE.search(text)
        or is_negative_city_action_safety
        or is_hotspot_connect
        or CROWDED_QUIET_RE.search(text)
        or SHORT_SCREEN_ONLY_RE.search(text)
    )
    is_passive_status = bool(
        AMBIENT_MANUAL_CONSENT_RE.search(text)
        or NO_ACTION_CAMERA_PRIVACY_STATUS_RE.search(text)
        or NO_ACTION_AUDIO_PRIVACY_STATUS_RE.search(text)
        or NO_ACTION_PLAYBACK_STATUS_RE.search(text)
        or LOW_BATTERY_PLAYBACK_STATUS_RE.search(text)
        or PASSIVE_STATUS_RE.search(text)
        or HOTSPOT_NO_ACTION_STATUS_RE.search(text)
        or NO_ACTION_CAPABILITY_ROUTER_RE.search(text)
        or NO_ACTION_FAILURE_GUARD_RE.search(text)
        or ACTION_FAILURE_SAFETY_RE.search(text)
        or NO_ACTION_CURRENT_STATUS_RE.search(text)
        or NO_ACTION_PREVIOUS_DISPATCH_RE.search(text)
        or LOW_CONFIDENCE_ACTION_GUARD_RE.search(text)
        or LOCAL_CONTROL_STATUS_RE.search(text)
        or WAKE_SOURCE_CANCEL_RE.search(text)
        or WAKE_SOURCE_GUARD_RE.search(text)
        or STORY_FOLLOWUP_RE.search(text)
        or UPCOMING_SONG_FOLLOWUP_RE.search(text)
        or PLAYLIST_FOLLOWUP_RE.search(text)
        or ROUTE_FOLLOWUP_RE.search(text)
        or ACTION_STATUS_FOLLOWUP_RE.search(text)
        or TTS_POLICY_FOLLOWUP_RE.search(text)
        or FROST_DIALOG_STATUS_FOLLOWUP_RE.search(text)
        or MEMORY_STATUS_FOLLOWUP_RE.search(text)
    )
    if is_wake and not is_wake_word_guide and not is_passive_status:
        armed_until = now + WAKE_WINDOW_SEC
    allowed = is_wake or was_open or is_safety or is_passive_status or is_wake_word_guide or not REQUIRE_WAKE
    if not allowed:
        publish_state("安静待命", f"安静待命：我听成「{text}」。请先叫我“弗洛斯特”或“音乐DJ”。", status="listening")
        print(f"[voice] standby transcript={text!r}", flush=True)
        return ""

    if dry_run:
        print(text)
        publish_state("已听到", f"识别到：{text}", status="idle")
        return text

    print(
        f"[voice] routed transcript={text!r} wake={is_wake} window={was_open} "
        f"safety={is_safety} passive_status={is_passive_status}",
        flush=True,
    )
    queue_voice_command(text)
    if is_safety:
        armed_until = 0.0
    elif is_wake_word_guide:
        armed_until = 0.0
    elif is_passive_status and not was_open:
        armed_until = 0.0
    elif not is_wake:
        armed_until = now + WAKE_WINDOW_SEC
    publish_state("语音点播", f"识别到：{text}", status="queued")
    return text


def rms16le(chunk):
    if len(chunk) < 2:
        return 0
    count = len(chunk) // 2
    samples = struct.unpack("<" + "h" * count, chunk[: count * 2])
    if not samples:
        return 0
    square_sum = sum(sample * sample for sample in samples)
    return int(math.sqrt(square_sum / len(samples)))


def write_wav(path, frames):
    with wave.open(path, "wb") as handle:
        handle.setnchannels(CHANNELS)
        handle.setsampwidth(SAMPLE_WIDTH)
        handle.setframerate(RATE)
        handle.writeframes(b"".join(frames))


def multipart_body(fields, files):
    boundary = f"----sunset-radio-{uuid.uuid4().hex}"
    chunks = []
    for name, value in fields.items():
        chunks.append(f"--{boundary}\r\n".encode("utf-8"))
        chunks.append(f'Content-Disposition: form-data; name="{name}"\r\n\r\n'.encode("utf-8"))
        chunks.append(str(value).encode("utf-8"))
        chunks.append(b"\r\n")
    for name, filename, content_type, data in files:
        chunks.append(f"--{boundary}\r\n".encode("utf-8"))
        chunks.append(
            f'Content-Disposition: form-data; name="{name}"; filename="{filename}"\r\n'.encode("utf-8")
        )
        chunks.append(f"Content-Type: {content_type}\r\n\r\n".encode("utf-8"))
        chunks.append(data)
        chunks.append(b"\r\n")
    chunks.append(f"--{boundary}--\r\n".encode("utf-8"))
    return boundary, b"".join(chunks)


def transcribe_command(wav_path):
    if not ASR_COMMAND:
        raise RuntimeError("SUNSET_ASR_COMMAND is empty")
    rendered = ASR_COMMAND.format(file=shlex.quote(wav_path), path=shlex.quote(wav_path))
    result = subprocess.run(
        rendered,
        shell=True,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=45,
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError((result.stderr or result.stdout or "ASR command failed").strip())
    return result.stdout.strip()


def transcribe(wav_path):
    if ASR_PROVIDER == "command":
        return transcribe_command(wav_path)
    raise RuntimeError(f"Unsupported SUNSET_ASR_PROVIDER={ASR_PROVIDER!r}")


def clean_target(target):
    text = " ".join(str(target or "").split()).strip(" ，。！？!?,.")
    text = re.sub(r"^(?:到|去|听|放|播放|切到|切下到|下啊到|天下到)\s*", "", text)
    return text.strip()


def replace_wake_tail(text):
    match = WAKE_RE.match(str(text or "").strip())
    if not match:
        return None
    tail = (match.groupdict().get("tail") or "").strip()
    if not tail:
        return text
    normalized_tail = normalize_asr_command(tail)
    return re.sub(re.escape(tail) + r"\s*$", normalized_tail, text, count=1)


def normalize_asr_command(text):
    text = str(text or "")
    wake_text = replace_wake_tail(text)
    if wake_text is not None:
        return wake_text
    if LOCAL_CONTROL_STATUS_RE.search(text):
        return text.strip()
    if NO_ACTION_CAMERA_PRIVACY_STATUS_RE.search(text):
        return text.strip()
    if NO_ACTION_AUDIO_PRIVACY_STATUS_RE.search(text):
        return text.strip()
    if NO_ACTION_PLAYBACK_STATUS_RE.search(text):
        return text.strip()
    if LOW_BATTERY_PLAYBACK_STATUS_RE.search(text):
        return text.strip()
    if HOTSPOT_NO_ACTION_STATUS_RE.search(text):
        return text.strip()
    if NO_ACTION_CAPABILITY_ROUTER_RE.search(text):
        return text.strip()
    if NO_ACTION_FAILURE_GUARD_RE.search(text):
        return text.strip()
    if ACTION_FAILURE_SAFETY_RE.search(text):
        return text.strip()
    if NO_ACTION_CURRENT_STATUS_RE.search(text):
        return text.strip()
    if NO_ACTION_PREVIOUS_DISPATCH_RE.search(text):
        return text.strip()
    if LOW_CONFIDENCE_ACTION_GUARD_RE.search(text):
        return text.strip()
    if WAKE_SOURCE_CANCEL_RE.search(text) or WAKE_SOURCE_GUARD_RE.search(text):
        return text.strip()

    skip_current_patterns = [
        r"(别播|别放|别唱).{0,4}这首(?:了|啦|吧|嘛)?",
        r"这首.{0,4}(别播|别放|别唱|切掉|换掉|跳过)(?:了|啦|吧|嘛)?",
        r"把这首.{0,4}(切掉|换掉|跳过)(?:了|啦|吧|嘛)?",
        r"^(?:切歌|切一下歌|换个歌|跳一首)(?:吧|啦|啊)?$",
    ]
    if any(re.search(pattern, text) for pattern in skip_current_patterns):
        return "这首跳过"

    pause_patterns = [
        r"(?:该|把|让|将)?\s*(?:这|这个|音乐|歌曲|歌|声音)?\s*.*(?:停\s*停止|停\s*了|停止|暂停|停一下|停一停|停一会儿|先停会儿)",
        r"赞成\s*一下\s*把\s*音乐\s*暂停\s*一下",
        r"(?:先\s*)?(?:把|将|让)\s*(?:声音|电台)\s*(?:先)?\s*关\s*(?:一下|一会儿|一会|会儿)?",
        r"(?:声音|电台|音乐|歌|歌曲)\s*先\s*关(?:掉|闭)?\s*(?:一下|一会儿|一会|会儿)?",
        r"(?:声音|电台|音乐|歌|歌曲)\s*关(?:掉|闭)?\s*(?:一下|一会儿|一会|会儿)",
        r"(?:先)?(?:别|不要)(?:再|继续)?(?:放歌|放音乐|播放音乐|播歌|播音乐|播|唱|放)了",
        r"(?:先)?(?:别|不要)(?:再|继续)?(?:唱|播|放)(?:了|啦)?.{0,6}(?:歇会儿|歇一会儿|休息会儿|休息一会儿)(?:吧)?(?:$|[，,。.!！?？\s])",
        r"(?:先)?(?:别|不要)(?:再|继续)?(?:出歌|出音乐|出声播歌)(?:了|啦)?(?:吧)?(?:$|[，,。.!！?？\s])",
        r"(?:先)?(?:别|不要)(?:再)?(?:接着|接上|续上|续播)\s*(?:播|放|唱|听|播放|放歌|播歌|放音乐|播音乐)?(?:了|啦)?(?:吧)?(?:$|[，,。.!！?？\s])",
        r"(?:先)?把(?:歌|音乐|声音|电台).{0,10}(?:按住|摁住|停住).{0,6}(?:别|不要).{0,4}(?:播|放|唱)(?:了|啦)?(?:吧)?(?:$|[，,。.!！?？\s])",
        r"等(?:一下|一会儿|一会|会儿|下)?.{0,4}再(?:放歌|播歌|放音乐|播音乐|放|播|唱)(?:了|啦)?(?:吧)?(?:$|[，,。.!！?？\s])",
        r"(?:声音|电台|音乐|歌|歌曲).{0,8}(?:先)?(?:收住|收一下|收一收)(?:了|啦)?(?:吧)?(?:$|[，,。.!！?？\s])",
        r"(?:先)?(?:把|让)?(?:电台|音乐|歌|歌曲|声音).{0,6}(?:静一静|安静一下|安静一会儿|安静会儿)",
        r"(?:先)?(?:关|关掉|关闭)\s*(?:一下|一会儿|一会|会儿)\s*(?:声音|电台|音乐)",
        r"(?:先)?(?:别|不要)(?:再)?\s*响(?:了|啦)(?:吧)?(?:$|[，,。.!！?？\s])",
    ]
    if any(re.search(pattern, text) for pattern in pause_patterns):
        return "暂停音乐"

    negative_playback_action_patterns = [
        r"(?:先别|先不要|别|不要|不用|不必|别再|不要再)\s*(?:切|换)\s*(?:一下)?\s*(?:下一首|下一曲|歌|歌曲)\s*(?:吧)?(?:$|[，,。.!！?？\s])",
        r"(?:先别|先不要|别|不要|不用|不必|别再|不要再)\s*(?:下一首|下一曲|下一个|再来一首|来下一首|换一首|换首|换歌|切歌|跳过|跳一首)\s*(?:吧)?(?:$|[，,。.!！?？\s])",
        r"(?:先别|先不要|别|不要|不用|不必|别再|不要再)\s*(?:继续|恢复|开始)\s*(?:播放|播放音乐|播放歌曲|放歌|放音乐|放歌曲|播|放|唱|电台|音乐|歌曲)?\s*(?:吧)?(?:$|[，,。.!！?？\s])",
        r"(?:先别|先不要|别|不要|不用|不必|别再|不要再)\s*(?:恢复|继续|接着|接上|续上)\s*(?:刚才|刚刚)?\s*(?:的)?\s*(?:电台|音乐|歌|歌曲|那首|那首歌|那支歌|那支曲子|那曲子)(?:了|啦)?\s*(?:吧)?(?:$|[，,。.!！?？\s])",
        r"(?:先别|先不要|别|不要|不用|不必|别再|不要再)\s*(?:刚才|刚刚)\s*(?:那首|那首歌|那支歌|那支曲子|那曲子)\s*(?:继续|接着(?:放|播|唱)?|回来)(?:了|啦)?\s*(?:吧)?(?:$|[，,。.!！?？\s])",
        r"(?:先别|先不要|别|不要|不用|不必|别再|不要再)\s*(?:打开|恢复)\s*(?:电台声音|播放声音|声音|外放|电台|音乐)\s*(?:吧)?(?:$|[，,。.!！?？\s])",
    ]
    if any(re.search(pattern, text) for pattern in negative_playback_action_patterns):
        return text.strip()

    hotspot_ready_text = re.search(
        r"(我(?:的)?手机|我(?:的)?热点|个人热点|手机网络|手机流量|手机热点|流量|蜂窝|热点).{0,8}(开了|打开了|开好了|已经开|已经打开|准备好了)",
        text,
    ) or re.search(
        r"(开了|打开了|开好了|已经开|已经打开|准备好了).{0,8}(我(?:的)?手机|我(?:的)?热点|个人热点|手机网络|手机流量|手机热点|流量|蜂窝|热点)",
        text,
    ) or re.search(
        r"(?:我)?.{0,4}(?:打开|开好|开启).{0,4}(?:个人热点|手机热点|手机流量|手机网络|流量|蜂窝|热点)(?:了|啦|啊)?",
        text,
    )
    if hotspot_ready_text:
        return text.strip()
    if re.search(r"(?<!不)(?:可以|能)出声(?!了?[吗么嘛])(?:了)?|你说吧", text):
        return text.strip()
    if re.search(
        r"(?:(?:有没有|是否|是不是|会不会|能不能|你|现在|当前).{0,8}"
        r"(?:开麦|打开麦|(?:开着|开|打开|开启).{0,8}(?:摄像头|相机|麦克风|话筒))|"
        r"(?:摄像头|相机|麦克风|话筒).{0,8}(?:会不会|会|是不是|是否|有没有|能不能).{0,8}(?:偷偷|自动)?.{0,4}(?:开|打开|开启))",
        text,
    ):
        return text.strip()
    if re.search(
        r"(?:长按|长摁|按住|摁住).{0,24}(?:会不会|是不是|是否|会|时|时候|还是|吗|嘛|么).{0,24}"
        r"(?:解除静音|打开电台|开电台|关掉播放|关闭播放|播放当前日落|当前日落|安静待命)",
        text,
    ):
        return text.strip()

    resume_play_patterns = [
        r"^(?:开始|继续|恢复|接着)\s*(?:放歌|放音乐|放歌曲|播放|播放音乐|播放歌曲|播|放|唱|听|听歌|听音乐|(?:刚才|刚刚)的歌|(?:刚才|刚刚)的音乐|(?:刚才|刚刚)那首(?:歌|音乐|曲子)?)\s*(?:吧)?$",
        r"^(?:可以|能|帮我|麻烦你)?\s*(?:继续|接着|恢复)\s*(?:播|放|唱|听)\s*(?:了|啦)?\s*(?:吧)?$",
        r"^(?:再|重新)\s*(?:开|打开)\s*(?:一下|一会儿|一会|会儿)?\s*(?:音乐|电台|播放|歌)\s*(?:吧)?$",
        r"^(?:声音|音乐|歌|歌曲|电台)\s*(?:回来|回来了|开回来|恢复回来|接回来|续回来)\s*(?:吧)?$",
        r"^(?:恢复|继续|接着|接上|续上)\s*(?:刚才|刚刚)?\s*(?:的)?\s*(?:电台|音乐|歌|歌曲|那首|那首歌|那支歌|那支曲子|那曲子)\s*(?:吧)?$",
        r"^(?:刚才|刚刚)\s*(?:那首|那首歌|那支歌|那支曲子|那曲子)\s*(?:继续(?:放|播|唱|听)?|接着(?:放|播|唱|听)?|回来|接回来|续回来)\s*(?:吧)?$",
        r"^(?:电台|音乐|歌|歌曲)\s*(?:继续起来|接着起来|重新起来)\s*(?:吧)?$",
        r"^(?:可以|能)\s*继续(?:了|啦)?\s*(?:吧)?$",
    ]
    if any(re.fullmatch(pattern, text.strip()) or re.search(pattern, text) for pattern in resume_play_patterns):
        return "继续播放音乐"

    open_patterns = [
        r"解除\s*进入",
        r"(?:解除|取消)\s*(?:静音|声音|对话)",
        r"(?:别|不要)\s*静音",
        r"(?:你|欢迎|帮我|给我)?\s*打开\s*了?\s*(?:电台声音|播放声音|声音|电台|音乐)?",
        r"(?:恢复|打开)\s*(?:声音|外放|播放声音|电台声音)",
        r"(?:把|将|让)?\s*(?:电台|音乐|歌曲|播放)?\s*声音\s*(?:开回来|回来|恢复回来)",
        r"^(?:继续|接着)\s*(?:响|出声)\s*$",
        r"^(?:继续|接着)\s*(?:播|放|唱)\s*(?:吧)?$",
        r"(?:别|不要)\s*(?:关着|关声音)",
        r"可以\s*(?:放歌|播放)",
        r"^(?:再|重新)?\s*开声\s*(?:吧)?$",
        r"声音\s*打开",
        r"^(?:把|将|让)?\s*(?:电台|音乐|歌曲|播放)?\s*声音\s*(?:打开|恢复|开起来)\s*$",
    ]
    if any(re.fullmatch(pattern, text.strip()) or re.search(pattern, text) for pattern in open_patterns):
        return "打开电台声音"

    play_patterns = [
        (
            r"^(?!.*(?:别|不要|不想|先别|别再)\s*(?:放|播|听|来点|整点|搞点|安排点|整一首|搞一首|安排一首))(?:请|麻烦)?\s*(?:帮|给)?\s*我?\s*(?:放下|放点|放一下|放一首|放首|放|来点|整点|搞点|安排点|整一首|搞一首|安排一首)\s*(?P<target>[^，。！？!?,]+?)\s*的\s*(?P<kind>歌曲|音乐|歌)",
            "播放{target}的{kind}",
        ),
        (
            r"(?:帮|把|当|让|给)?\s*我?\s*(?:来一首|来首|听一下|听听|想听|听)\s*(?P<target>[^，。！？!?,]+?)\s*的\s*(?P<kind>歌曲|音乐|歌)",
            "播放{target}的{kind}",
        ),
        (
            r"(?:帮|把|当|让|给)?\s*我?\s*(?:来一首|来首)\s*(?P<target>[^，。！？!?,]+)",
            "播放{target}",
        ),
        (
            r"(?:帮|把|当|让|给)?\s*我\s*(?:放下|放一下|播放|放)\s*(?P<target>[^，。！？!?,]+?)\s*的\s*(?P<kind>歌曲|音乐|歌)",
            "播放{target}的{kind}",
        ),
        (
            r"(?:下\s*啊\s*到|天\s*下\s*到|天下\s*到|切\s*下\s*到|切下\s*到|切\s*到|到|去)\s*(?P<target>[^，。！？!?,]+?)\s*的\s*(?P<kind>歌曲|音乐|歌)",
            "播放{target}的{kind}",
        ),
        (
            r"(?:帮|把|当|让|给)?\s*我\s*(?:放下|放一下|播放|放)\s*(?P<target>[^，。！？!?,]+)",
            "播放{target}",
        ),
    ]
    for pattern, repl in play_patterns:
        match = re.search(pattern, text)
        if not match:
            continue
        target = clean_target(match.group("target"))
        if not target:
            continue
        kind = match.groupdict().get("kind") or ""
        return re.sub(pattern, repl.format(target=target, kind=kind), text, count=1)
    return text


def clean_transcript(text):
    text = " ".join(str(text or "").replace("\u3000", " ").split()).strip(" ，。！？!?,.")
    if len(text) <= 1:
        return text if text in {"嘘"} else ""
    lowered = text.lower()
    ignored = [
        "字幕",
        "谢谢观看",
        "subscribe",
        "amara.org",
    ]
    if any(item in lowered for item in ignored):
        return ""
    return normalize_asr_command(text)


def start_arecord():
    if not shutil.which(ARECORD):
        raise RuntimeError(f"{ARECORD} not found; install alsa-utils or set SUNSET_ARECORD")
    return subprocess.Popen(
        [
            ARECORD,
            "-q",
            "-D",
            MIC_DEVICE,
            "-f",
            "S16_LE",
            "-r",
            str(RATE),
            "-c",
            str(CHANNELS),
            "-t",
            "raw",
        ],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )


def read_chunk(proc):
    if not proc.stdout:
        return b""
    return proc.stdout.read(CHUNK_BYTES)


def calibrate(proc):
    chunks = max(1, int(CALIBRATE_SEC * 1000 / CHUNK_MS))
    values = []
    for _ in range(chunks):
        chunk = read_chunk(proc)
        if not chunk:
            break
        values.append(rms16le(chunk))
    baseline = int(sum(values) / len(values)) if values else 0
    return max(MIN_RMS, int(baseline * THRESHOLD_MULT))


def speech_segments():
    proc = start_arecord()
    try:
        threshold = calibrate(proc)
        publish_state("语音待命", "语音控制已开始监听。", status="listening")
        pre_chunks = max(1, int(PRE_ROLL_MS / CHUNK_MS))
        start_chunks = max(1, int(START_MS / CHUNK_MS))
        end_chunks = max(1, int(END_SILENCE_MS / CHUNK_MS))
        max_chunks = max(1, int(MAX_SEGMENT_SEC * 1000 / CHUNK_MS))
        min_chunks = max(1, int(MIN_SEGMENT_SEC * 1000 / CHUNK_MS))
        pre_roll = deque(maxlen=pre_chunks)
        speaking = False
        segment = []
        voice_count = 0
        silence_count = 0
        while True:
            chunk = read_chunk(proc)
            if not chunk:
                raise RuntimeError("microphone stream ended")
            level = rms16le(chunk)
            if not speaking:
                pre_roll.append(chunk)
                if level >= threshold:
                    voice_count += 1
                else:
                    voice_count = 0
                if voice_count >= start_chunks:
                    speaking = True
                    segment = list(pre_roll)
                    silence_count = 0
                    voice_count = 0
                    publish_state("已听到", "听到声音，正在收一句话。", status="listening")
                continue

            segment.append(chunk)
            if level < threshold:
                silence_count += 1
            else:
                silence_count = 0
            if len(segment) >= max_chunks or (len(segment) >= min_chunks and silence_count >= end_chunks):
                yield segment
                speaking = False
                segment = []
                pre_roll.clear()
                voice_count = 0
                silence_count = 0
                time.sleep(COOLDOWN_SEC)
    finally:
        proc.terminate()
        try:
            proc.wait(timeout=1)
        except subprocess.TimeoutExpired:
            proc.kill()


def handle_frames(frames, dry_run=False):
    os.makedirs(TMP_DIR, exist_ok=True)
    path = os.path.join(TMP_DIR, f"sunset-voice-{int(time.time())}-{uuid.uuid4().hex[:8]}.wav")
    try:
        write_wav(path, frames)
        publish_state("转文字", "正在把这句话转成文字。", status="thinking")
        text = clean_transcript(transcribe(path))
        if not text:
            publish_state("语音待命", "没有听清，继续监听。", status="listening")
            return ""
        return route_transcript(text, dry_run=dry_run)
    except Exception as exc:
        publish_state("语音待查", "这句话没听清，我继续等下一句。", status="idle")
        print(f"[voice] {exc}", flush=True)
        return ""
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass


def listen_forever(dry_run=False):
    while True:
        try:
            for frames in speech_segments():
                handle_frames(frames, dry_run=dry_run)
        except KeyboardInterrupt:
            raise
        except Exception as exc:
            publish_state("语音待查", "麦克风监听稍后自动重试。", status="idle")
            print(f"[voice] restarting after error: {exc}", flush=True)
            time.sleep(5)


def main():
    parser = argparse.ArgumentParser(description="Listen to a microphone, transcribe speech, and send Sunset Radio voice commands.")
    parser.add_argument("--file", help="Transcribe one existing wav/mp3 file instead of listening to the microphone.")
    parser.add_argument("--text", help="Route one already-transcribed phrase; useful for testing wake windows.")
    parser.add_argument("--dry-run", action="store_true", help="Print recognized text but do not queue a command.")
    args = parser.parse_args()

    if args.text:
        text = route_transcript(args.text, dry_run=args.dry_run)
        return 0 if text or args.dry_run else 1

    if args.file:
        text = clean_transcript(transcribe(args.file))
        if args.dry_run:
            print(text)
        elif text:
            text = route_transcript(text)
        return 0 if text else 1

    listen_forever(dry_run=args.dry_run)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
